{
  "implementation": "def solve(case):
    nodes = case["nodes"]
    core = case["core_distance"]
    dists = case["distances"]
    n = len(nodes)
    edge_dist = {}
    for u, v, d in dists:
        if u < v:
            key = (u, v)
        else:
            key = (v, u)
        edge_dist[key] = d
    edges = []
    for (u, v), d in edge_dist.items():
        w = max(core[u], core[v], d)
        edges.append((w, u, v))
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        xr = find(x)
        yr = find(y)
        if xr == yr:
            return False
        if rank[xr] < rank[yr]:
            parent[xr] = yr
        elif rank[yr] < rank[xr]:
            parent[yr] = xr
        else:
            parent[yr] = xr
            rank[xr] += 1
        return True
    mst_edges = []
    total_weight = 0.0
    for w, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total_weight += w
            if len(mst_edges) == n - 1:
                break
    if len(mst_edges) != n - 1:
        raise ValueError("Graph is disconnected, cannot compute MST")
    return {"mst_edges": mst_edges, "total_weight": total_weight}"
}
